#!/usr/bin/env python3

"""
Script to reproduce the DNS-1123 compliance issue with metadata.name in DLF YAML.
"""

from metadata_converter.generate import generate_dlf_yaml_dict
import re

def test_dns_compliance():
    """Test various problematic names to reproduce the issue."""

    # Test cases with problematic names
    test_cases = [
        {
            "name": "Finance Proposition Bank",
            "expected_valid": False,  # Contains spaces - should fail DNS-1123 validation
            "description": "Original issue example"
        },
        {
            "name": "NOAA Weather Data – JFK Airport", 
            "expected_valid": False,  # Contains spaces and en-dash
            "description": "From jfk.yaml"
        },
        {
            "name": "Lorem ipsum data set",
            "expected_valid": False,  # Contains spaces
            "description": "From lorem_ipsum.yaml"
        },
        {
            "name": "Groningen Meaning Bank – Modified",
            "expected_valid": False,  # Contains spaces and en-dash
            "description": "From gmb.yaml"
        },
        {
            "name": "IBM Debater® Thematic Clustering of Sentences",
            "expected_valid": False,  # Contains spaces and special char
            "description": "From thematic_clustering.yaml"
        },
        {
            "name": "valid-name-123",
            "expected_valid": True,  # Already compliant
            "description": "Already valid DNS-1123 name"
        }
    ]

    # DNS-1123 regex pattern from Kubernetes
    dns_1123_regex = re.compile(r'^[a-z0-9]([-a-z0-9]*[a-z0-9])?(\.[a-z0-9]([-a-z0-9]*[a-z0-9])?)*$')

    print("Testing DNS-1123 compliance of generated metadata names...\n")

    for i, test_case in enumerate(test_cases, 1):
        print(f"Test {i}: {test_case['description']}")
        print(f"  Input name: '{test_case['name']}'")

        # Create minimal input data
        input_data = {
            "name": test_case['name'],
            "version": "1.0",
            "repository": {
                "url": "http://example.com/data.tar.gz",
                "mime_type": "application/x-tar"
            }
        }

        # Generate DLF YAML
        try:
            result = generate_dlf_yaml_dict(input_data)
            generated_name = result['metadata']['name']
            print(f"  Generated name: '{generated_name}'")

            # Check DNS-1123 compliance
            is_compliant = bool(dns_1123_regex.match(generated_name))
            print(f"  DNS-1123 compliant: {is_compliant}")
            print(f"  Expected valid: {test_case['expected_valid']}")

            if is_compliant != test_case['expected_valid']:
                if test_case['expected_valid']:
                    print(f"  ❌ UNEXPECTED: Should be valid but failed validation")
                else:
                    print(f"  ❌ ISSUE REPRODUCED: Contains invalid characters")
            else:
                if test_case['expected_valid']:
                    print(f"  ✅ CORRECT: Valid name correctly accepted")
                else:
                    print(f"  ⚠️  WARNING: Invalid name unexpectedly passed validation")

        except Exception as e:
            print(f"  ❌ ERROR: {e}")

        print()

def validate_dns_1123(name):
    """Validate if a name complies with DNS-1123 subdomain format."""
    dns_1123_regex = re.compile(r'^[a-z0-9]([-a-z0-9]*[a-z0-9])?(\.[a-z0-9]([-a-z0-9]*[a-z0-9])?)*$')
    return bool(dns_1123_regex.match(name))

if __name__ == "__main__":
    test_dns_compliance()

    # Additional validation of the regex
    print("\nDNS-1123 regex validation examples:")
    test_names = [
        "valid-name",
        "valid-name-123",
        "also.valid.com",
        "Finance Proposition Bank",  # Invalid - spaces
        "UPPERCASE",  # Invalid - uppercase  
        "-invalid-start",  # Invalid - starts with dash
        "invalid-end-",  # Invalid - ends with dash
        "valid123name"  # Valid
    ]

    for name in test_names:
        compliant = validate_dns_1123(name.lower() if name.isupper() else name)
        print(f"  '{name}' -> {'✅ compliant' if compliant else '❌ non-compliant'}")

