"""
Final verification that the DNS-1123 compliance fix works correctly.
"""

from metadata_converter.generate import generate_dlf_yaml_dict
import re

def validate_dns_1123(name):
    """Validate if a name complies with DNS-1123 subdomain format."""
    dns_1123_regex = re.compile(r'^[a-z0-9]([-a-z0-9]*[a-z0-9])?(\.[a-z0-9]([-a-z0-9]*[a-z0-9])?)*$')
    return bool(dns_1123_regex.fullmatch(name))

def main():
    print("🔍 FINAL VERIFICATION: DNS-1123 Compliance Fix")
    print("=" * 50)

    # Test the exact case from the issue description
    test_cases = [
        {
            "name": "Finance Proposition Bank",
            "expected_sanitized": "finance-proposition-bank",
            "description": "Original issue example"
        },
        {
            "name": "NOAA Weather Data – JFK Airport", 
            "expected_sanitized": "noaa-weather-data-jfk-airport",
            "description": "Real dataset with en-dash"
        },
        {
            "name": "Lorem ipsum data set",
            "expected_sanitized": "lorem-ipsum-data-set",
            "description": "Spaces to hyphens"
        },
        {
            "name": "UPPERCASE-NAME",
            "expected_sanitized": "uppercase-name",
            "description": "Uppercase to lowercase"
        },
        {
            "name": "valid-name-123",
            "expected_sanitized": "valid-name-123",
            "description": "Already compliant (should remain unchanged)"
        }
    ]

    all_passed = True

    for i, test_case in enumerate(test_cases, 1):
        print(f"\nTest {i}: {test_case['description']}")
        print(f"  Input:    '{test_case['name']}'")

        # Create test input data
        input_data = {
            "name": test_case['name'],
            "version": "1.0",
            "repository": {
                "url": "http://example.com/data.tar.gz",
                "mime_type": "application/x-tar"
            }
        }

        # Generate DLF YAML
        result = generate_dlf_yaml_dict(input_data)
        generated_name = result['metadata']['name']

        print(f"  Output:   '{generated_name}'")

        # Validate DNS-1123 compliance
        is_compliant = validate_dns_1123(generated_name)
        print(f"  Compliant: {'✅ YES' if is_compliant else '❌ NO'}")

        # Check if it matches expected (if provided)
        if 'expected_sanitized' in test_case:
            matches_expected = generated_name == test_case['expected_sanitized']
            print(f"  Expected: {'✅ YES' if matches_expected else '❌ NO'} ('{test_case['expected_sanitized']}')")
            if not matches_expected:
                all_passed = False

        if not is_compliant:
            all_passed = False

    print("\n" + "=" * 50)
    if all_passed:
        print("🎉 SUCCESS: All tests passed! DNS-1123 compliance issue is FIXED.")
        print("\n📋 Summary of fixes:")
        print("   • Names with spaces are converted to hyphens")
        print("   • Uppercase letters are converted to lowercase") 
        print("   • Special characters are removed or replaced")
        print("   • Names are validated to meet Kubernetes DNS-1123 standards")
        print("   • Original input data remains unchanged")
        return True
    else:
        print("❌ FAILURE: Some tests failed.")
        return False

if __name__ == "__main__":
    success = main()
    exit(0 if success else 1)
